<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Product approval | Lokal Culture</title><link rel="stylesheet" href="/assets/css/app.css"><link rel="stylesheet" href="/assets/css/vendor.css"><link rel="stylesheet" href="/assets/css/admin.css"></head>
<body class="dashboard-page"><header class="site-header"><a class="brand" href="/">✦ LOKAL <em>CULTURE</em></a><nav class="header-actions"><a href="/account">Dashboard</a><a href="/logout">Sign out</a></nav></header><main class="vendor-management"><div class="management-heading"><div><p class="eyebrow">Administrator workspace</p><h1>Product approval</h1><p>Review new products before they reach the public collection.</p></div><span><?= count($products) ?> pending</span></div><div class="approval-grid"><?php foreach ($products as $product): ?><article class="approval-card"><img src="<?= htmlspecialchars($product['image']) ?>" alt="<?= htmlspecialchars($product['name']) ?>"><div><p class="eyebrow"><?= htmlspecialchars($product['category']) ?> · <?= htmlspecialchars($product['vendor']) ?></p><h2><?= htmlspecialchars($product['name']) ?></h2><strong><?= htmlspecialchars($product['price']) ?></strong><p><?= htmlspecialchars($product['description']) ?></p><div class="approval-actions"><form method="post"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken) ?>"><input type="hidden" name="product_id" value="<?= htmlspecialchars($product['id']) ?>"><button class="button" name="decision" value="approve" type="submit">Approve</button></form><form method="post"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken) ?>"><input type="hidden" name="product_id" value="<?= htmlspecialchars($product['id']) ?>"><button class="button button-muted" name="decision" value="reject" type="submit">Reject</button></form></div></div></article><?php endforeach; ?></div><?php if (!$products): ?><p class="empty-state">Nothing is waiting for review.</p><?php endif; ?></main></body></html>